import{_ as n,B as o,o as t,c as s,a8 as a,d as l,w as r,f as d,E as c,af as p}from"./chunks/framework.CNIpabDg.js";const v=JSON.parse(`{"title":"Package management architecture","description":"How Xila's shared package tooling, community registry and future on-device installer fit together.","frontmatter":{"layout":"doc","docType":"explanation","description":"How Xila's shared package tooling, community registry and future on-device installer fit together."},"headers":[],"relativePath":"explanation/package-management.md","filePath":"explanation/package-management.md","lastUpdated":1793045410000}`),h={name:"explanation/package-management.md"};function g(u,e,m,f,b,y){const i=o("Mermaid");return t(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793045410000"},[e[1]||(e[1]=a('<h1 id="package-management-architecture" tabindex="-1">Package management architecture <a class="header-anchor" href="#package-management-architecture" aria-label="Permalink to &quot;Package management architecture&quot;">​</a></h1><p>Xila&#39;s application distribution is split across <strong>three repositories</strong>. As of 26 October 2026, authoring and inspecting development archives and generating a static <strong>unsigned registry preview</strong> work; downloading, authenticating and installing third-party packages on Xila <strong>does not</strong>.</p><p>The repositories and APIs are being developed under <a href="https://github.com/xila-project/core/issues/308" target="_blank" rel="noreferrer">Core #308</a>, the <a href="https://github.com/xila-project/core/issues/402" target="_blank" rel="noreferrer">package format decision #402</a>, and the <a href="https://github.com/xila-project/core/issues/536" target="_blank" rel="noreferrer">shared workspace extraction #536</a>. The experimental <code>.xpk</code> extension, TAR profile and manifest schema are <strong>not frozen for production</strong>.</p><h2 id="repository-ownership" tabindex="-1">Repository ownership <a class="header-anchor" href="#repository-ownership" aria-label="Permalink to &quot;Repository ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repository</th><th>Owns today</th><th>Does not own</th></tr></thead><tbody><tr><td><a href="https://github.com/xila-project/package_manager" target="_blank" rel="noreferrer"><code>Xila-Project/package_manager</code></a></td><td>Shared verification, provisional manifest, TAR reader/writer, native <code>xila-package</code> builder and Cargo/mise CI</td><td>Xila VFS, network drivers, package trust policy, implemented installer</td></tr><tr><td><a href="https://github.com/xila-project/registry" target="_blank" rel="noreferrer"><code>xila-project/registry</code></a></td><td>Contributor TOML declarations, strict validation and static GitHub Pages <strong>preview</strong> generation</td><td>Rust manifest/reader libraries, packages themselves, authenticated repository indexes</td></tr><tr><td><a href="https://github.com/xila-project/core" target="_blank" rel="noreferrer"><code>Xila-Project/core</code></a></td><td>Runtime VFS/Wasmi/application loader, firmware prototype and <strong>pinned shared verification dependency</strong></td><td>A working <code>pkg</code> command, package installation/activation, on-device package-repository client</td></tr></tbody></table><p>The actual Rust workspace is named <strong><code>package_manager</code></strong> (underscore). Its Cargo package names use <code>xila-package-…</code> prefixes, for example <code>xila-package-manifest</code>. The eventual installed Xila package manager must not be confused with that development repository.</p>',6)),(t(),l(p,null,{default:r(()=>[c(i,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Author%5BApplication%20developer%5D%20--%3E%7Cbuild%20files%20and%20JSON%20manifest%7C%20Builder%5BShared%20native%20xila-package%20builder%5D%0A%20%20%20%20Builder%20--%3E%7Cexperimental%20XPK%20TAR%20archive%7C%20Release%5BExternal%20immutable%20release%20artifact%5D%0A%20%20%20%20Author%20--%3E%7Creviewed%20TOML%20declaration%7C%20Registry%5Bregistry%20repository%5D%0A%20%20%20%20Registry%20--%3E%7Cunsigned%20per-package%20JSON%20preview%7C%20Pages%5BStatic%20Pages%20preview%5D%0A%20%20%20%20Core%5BXila%20Core%5D%20--%3E%7Cpinned%20Git%20dependency%7C%20Verification%5BShared%20SHA-256%20and%20strict%20Ed25519%5D%0A%20%20%20%20Installer%5BFuture%20offline%20installer%20and%20repository%20client%5D%20-.-%3E%7Cplanned%20only%7C%20Release%0A%20%20%20%20Installer%20-.-%3E%7Cplanned%20authenticated%20metadata%7C%20Pages%0A%20%20%20%20Installer%20-.-%3E%7Cplanned%20VFS%20and%20loader%20integration%7C%20Core%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p><strong>Dependency direction:</strong> shared package libraries must depend on neither Core nor the community registry. Core and the registry may consume the shared tools. Any Core-specific disk, task, permissions, loader or networking implementation belongs in Core, not in the portable format crates.</p><h2 id="what-exists-versus-what-is-still-planned" tabindex="-1">What exists versus what is still planned <a class="header-anchor" href="#what-exists-versus-what-is-still-planned" aria-label="Permalink to &quot;What exists versus what is still planned&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Current status</th></tr></thead><tbody><tr><td>Versioned JSON manifest, validated paths/files/hashes</td><td>Provisional Rust implementation</td></tr><tr><td>Deterministic uncompressed USTAR archive generation</td><td>Native host tool implemented</td></tr><tr><td>Full-buffer TAR inspection and optional verification with caller-supplied Ed25519 public key</td><td>Implemented, <strong>not streamable</strong></td></tr><tr><td>SHA-256 streaming and strict Ed25519 primitives</td><td>Shared and used by Core</td></tr><tr><td>Contributor declaration validation and direct-path static JSON preview</td><td>Implemented, <strong>unsigned</strong></td></tr><tr><td>Trust-root provisioning, signed repository index, authenticated publisher roles</td><td><strong>Not implemented</strong></td></tr><tr><td>Streaming archive extraction with MCU-bounded RAM, optional decompression</td><td><strong>Not implemented</strong></td></tr><tr><td>Transactional package install/upgrade/remove, installed-package database</td><td><strong>Not implemented</strong></td></tr><tr><td>In-Xila <code>pkg</code> CLI or GUI, version/dependency resolution, loader enforcement</td><td><strong>Not implemented</strong></td></tr></tbody></table><p>The <code>xila-package-manager</code> Cargo crate currently contains <strong>only a scaffold</strong>, not an install API. Core&#39;s signed <strong>firmware</strong> update prototype is separate and must not be mistaken for an <strong>application</strong> package installer.</p><h2 id="security-model-and-why-a-checksum-is-not-enough" tabindex="-1">Security model and why a checksum is not enough <a class="header-anchor" href="#security-model-and-why-a-checksum-is-not-enough" aria-label="Permalink to &quot;Security model and why a checksum is not enough&quot;">​</a></h2><p>A package can have a valid SHA-256 hash and still be malicious or substituted when the expected hash came from <strong>unsigned metadata</strong>. A secure future workflow needs three separate checks:</p><ol><li><strong>Repository identity:</strong> authenticate a repository or publisher with keys trusted <strong>outside</strong> the downloaded metadata; protect versions against rollback or freeze attacks.</li><li><strong>Package integrity and origin:</strong> authenticate a signed, versioned manifest that covers every install-relevant file, size, path, hash, target, ABI and requested capability; verify the complete payload.</li><li><strong>Installation and execution authorization:</strong> stage files safely, commit atomically, track ownership/version and enforce the package&#39;s permissions on launch. A valid publisher signature alone <strong>must not grant privileged VFS or device access</strong>.</li></ol><p>Today&#39;s reader can verify the manifest with an externally trusted public key, but there is no built-in key authorization or installation transaction. The static registry&#39;s JSON is <strong>not signed</strong>. HTTPS alone does not replace either trust decision.</p><h2 id="why-the-current-tar-implementation-is-not-yet-mcu-ready" tabindex="-1">Why the current TAR implementation is not yet MCU-ready <a class="header-anchor" href="#why-the-current-tar-implementation-is-not-yet-mcu-ready" aria-label="Permalink to &quot;Why the current TAR implementation is not yet MCU-ready&quot;">​</a></h2><p>The initial design uses <code>tar-no-std</code> over a borrowed <strong>complete archive byte slice</strong>, and the Miniserde manifest parser requires <code>alloc</code>. The host builder also loads all payloads into memory and rereads the resulting archive. None of these paths provides bounded-memory installation from an unseekable HTTP stream.</p><p>Before shipping to ESP32-S3, <a href="https://github.com/xila-project/core/issues/402" target="_blank" rel="noreferrer">format issue #402</a> must compare restricted TAR, CPIO <code>newc</code>, SWUpdate/IPK/APK ideas and small custom framing using actual parser/stack/flash/RAM measurements. Whatever container is selected must authenticate bounded metadata before interpreting untrusted payloads, stream per-file hashes into non-executable staging, reject unexpected archive semantics, and recover from failures before activation.</p><h2 id="follow-up-ownership" tabindex="-1">Follow-up ownership <a class="header-anchor" href="#follow-up-ownership" aria-label="Permalink to &quot;Follow-up ownership&quot;">​</a></h2><ul><li><a href="https://github.com/xila-project/core/issues/402" target="_blank" rel="noreferrer">#402</a>: canonical signed bytes, container choice and streaming archive reader.</li><li><a href="https://github.com/xila-project/core/issues/491" target="_blank" rel="noreferrer">#491</a>: offline trusted installation, staging, ownership and crash recovery.</li><li><a href="https://github.com/xila-project/core/issues/492" target="_blank" rel="noreferrer">#492</a>: optional authenticated repository metadata and lightweight dependency planning.</li><li><a href="https://github.com/xila-project/core/issues/493" target="_blank" rel="noreferrer">#493</a>: in-target package command interface.</li><li><a href="https://github.com/xila-project/core/issues/494" target="_blank" rel="noreferrer">#494</a>: host authoring/signing/inspection tools.</li><li><a href="https://github.com/xila-project/core/issues/495" target="_blank" rel="noreferrer">#495</a>: runtime loader verification and time-of-check/time-of-use enforcement.</li><li><a href="https://github.com/xila-project/core/issues/536" target="_blank" rel="noreferrer">#536</a>: shared-repository integration and format source of truth.</li></ul><h2 id="continue" tabindex="-1">Continue <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;Continue&quot;">​</a></h2><ul><li><a href="/reference/package-format.html">Prototype package format and API</a>.</li><li><a href="/how-to/package-application.html">Create a development package</a>.</li><li><a href="/how-to/submit-package.html">Contribute a registry declaration</a>.</li><li><a href="/explanation/architecture/libraries/verification.html">Shared verification</a>.</li><li><a href="/explanation/architecture/libraries/firmware_update.html">Firmware update prototype</a> — a separate mechanism.</li></ul>',15))])}const w=n(h,[["render",g]]);export{v as __pageData,w as default};
